begin;
-- Wait for a running market tick, keep scheduled jobs out until commit (avoids deadlocks).
select pg_advisory_xact_lock(7311001);

-- ===== supabase/updates/20261204007300_company_reputation.sql =====
-- ===== idempotent copy of migrations/20261204007300_company_reputation.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 7300 · Reputation for every player company, an hourly close that never fails on its extras (ADR-183)
-- =============================================================================
-- * Before: only listed companies had a reputation (listed_companies.reputation, ADR-167), and its target moved only
--   with payouts, dividends, investments, research and scandals. A listed company without those sat at exactly 50
--   ("Ruf bewegt sich nicht"); private companies had none, although the dashboard spoke of it.
-- * Now: player_companies.reputation for every company (listed ones mirror listed_companies.reputation, which stays
--   the source for all listed rules). Each closed hour judges quality, delivery, price, wages, bills, crises and a
--   running campaign (company_reputation_drivers, port of reputationDrivers in src/lib/sim/company-reputation.ts);
--   listed companies add these to their shareholder target. The hour row keeps value, target and drivers.
-- * The reputation moves the demand of private companies too (listed_hour_effect, companyHealth.reputation).
-- * CEO interviews move the reputation of every company (company_interview_finish), tax penalties keep their
--   one-off drops (listed_reputation_bump now also updates the mirror).
-- * listed_hour_after runs every extra step (projects, quits and notices, fair value, missions, tax office, board,
--   reputation) in its own sub-block: an error there is logged in job_runs ('company_hour_step') and shown on the
--   dashboard, but never rolls back the company's hour again (one failing extra used to cost the whole hour: no
--   hours, no "Verlauf", every "bringt" 0 €, a frozen reputation).
-- All functions are full redefinitions (no text patches), so small differences of the live function text do not
-- matter. Idempotent: runs unchanged as supabase/updates/20261204007300_company_reputation.sql.

-- ---------------------------------------------------------------------------
-- A. Schema
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists reputation double precision not null default 50;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_companies_reputation_check'
                    and conrelid = 'public.player_companies'::regclass) then
    alter table public.player_companies
      add constraint player_companies_reputation_check check (reputation between 0 and 100);
  end if;
end;
$$;
comment on column public.player_companies.reputation is
  'Reputation of the company 0..100 (ADR-183), every company; listed companies mirror listed_companies.reputation.';
alter table public.player_company_hours add column if not exists reputation double precision;
alter table public.player_company_hours add column if not exists reputation_target double precision;
alter table public.player_company_hours add column if not exists reputation_drivers jsonb;
comment on column public.player_company_hours.reputation_drivers is
  'What moved the reputation target this hour (ADR-183): quality, delivery, price, wages, bills, crisis, campaign '
  '(and for listed companies base, items, greed, reinvest, dividends, scandal).';

-- listed companies start from what they had as listed companies
update public.player_companies pc set reputation = l.reputation
  from public.listed_companies l
 where l.company_id = pc.company_id and pc.reputation <> l.reputation;

-- ---------------------------------------------------------------------------
-- B. Rules (ports of src/lib/sim/company-reputation.ts)
-- ---------------------------------------------------------------------------
create or replace function public.company_reputation_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('companyHealth') -> 'reputation', '{}'::jsonb);
$$;

-- reputationDrivers: points per driver, 0 is neutral
create or replace function public.company_reputation_drivers(p_quality double precision, p_demand double precision,
  p_capacity double precision, p_price_level text, p_pay_factor_bps integer, p_unpaid bigint, p_severity integer,
  p_campaign boolean)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg       jsonb := public.company_reputation_cfg();
  v_q       double precision := least(1.0, greatest(0.0, coalesce(p_quality, 0)));
  v_neutral double precision := least(0.99, greatest(0.01, public.cfg_num(cfg, '{qualityNeutral}', 0.4)));
  v_rel     double precision;
  v_served  double precision;
  v_paid    double precision := least(1.0, greatest(0.0, coalesce(p_pay_factor_bps, 10000) / 10000.0));
  v_premium double precision := public.config_double('startups', '{pricing,premiumMinQuality}', 0.5);
begin
  v_rel := case when v_q >= v_neutral then (v_q - v_neutral) / (1 - v_neutral) else (v_q - v_neutral) / v_neutral end;
  v_served := case when coalesce(p_demand, 0) > 0 then least(1.0, greatest(0.0, coalesce(p_capacity, 0) / p_demand)) else 1 end;
  return jsonb_build_object(
    'quality', case when v_rel >= 0 then public.cfg_num(cfg, '{qualityMax}', 10) * v_rel
                    else public.cfg_num(cfg, '{qualityMaxLoss}', 5) * v_rel end,
    'delivery', -public.cfg_num(cfg, '{deliveryMaxLoss}', 8) * (1 - v_served),
    'price', case when p_price_level = 'premium' and v_q < v_premium then -public.cfg_num(cfg, '{premiumLowQualityLoss}', 6)
                  when p_price_level = 'budget' then public.cfg_num(cfg, '{budgetGain}', 2)
                  else 0 end,
    'wages', -public.cfg_num(cfg, '{wagesMaxLoss}', 10) * (1 - v_paid),
    'bills', case when coalesce(p_unpaid, 0) > 0 then -public.cfg_num(cfg, '{billsLoss}', 6) else 0 end,
    'crisis', -public.cfg_num(cfg, '{crisisPerSeverity}', 3) * least(3, greatest(0, coalesce(p_severity, 0))),
    'campaign', case when coalesce(p_campaign, false) then public.cfg_num(cfg, '{campaignGain}', 3) else 0 end);
end;
$$;

-- reputationTargetAll: base (or the listed target) + the drivers, 0..100
create or replace function public.company_reputation_target(p_drivers jsonb, p_listed_target double precision default null)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select least(100.0, greatest(0.0,
           coalesce(p_listed_target, public.cfg_num(public.company_reputation_cfg(), '{base}', 50))
           + coalesce((select sum(v::double precision) from jsonb_each_text(coalesce(p_drivers, '{}'::jsonb)) x(k, v)), 0)));
$$;

-- reputationDemandFactor
create or replace function public.company_reputation_demand_factor(p_value double precision)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select 1 + public.cfg_num(public.company_reputation_cfg(), '{demandMaxEffect}', 0.2)
             * (least(100.0, greatest(0.0, coalesce(p_value, 50))) - 50) / 50.0;
$$;

-- The drivers of one closed hour of a company, from what the hour and the company show
create or replace function public.company_reputation_drivers_of(p_company uuid, p_hour_start timestamptz,
  p_demand double precision, p_capacity double precision, p_pay_factor_bps integer)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc    public.player_companies;
  v_sev integer;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return '{}'::jsonb;
  end if;
  select max(e.severity) into v_sev from public.player_company_events e
   where e.company_id = p_company and e.polarity = 'crisis' and e.status in ('open', 'in_force');
  return public.company_reputation_drivers(pc.quality, p_demand, p_capacity, pc.price_level::text, p_pay_factor_bps,
                                           pc.unpaid_cents, coalesce(v_sev, 0),
                                           (public.company_campaign_at(p_company, p_hour_start)).id is not null);
end;
$$;

-- Stores the reputation of the hour: the company (and its listed mirror) and the hour row
create or replace function public.company_reputation_record(p_company uuid, p_hour_start timestamptz, p_value double precision,
  p_target double precision, p_drivers jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.player_companies set reputation = least(100.0, greatest(0.0, p_value)) where company_id = p_company;
  update public.player_company_hours
     set reputation = least(100.0, greatest(0.0, p_value)), reputation_target = p_target, reputation_drivers = p_drivers
   where company_id = p_company and hour_start = date_trunc('hour', p_hour_start);
end;
$$;

-- One-off change of any company's reputation (interviews; tax penalties of listed companies)
create or replace function public.company_reputation_bump(p_company uuid, p_points double precision)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(p_points, 0) = 0 then
    return;
  end if;
  update public.player_companies set reputation = least(100.0, greatest(0.0, reputation + p_points))
   where company_id = p_company;
  update public.listed_companies set reputation = least(100.0, greatest(0.0, reputation + p_points))
   where company_id = p_company;
end;
$$;

-- An extra step of the hourly close failed: logged and shown, the hour itself stays
create or replace function public.company_close_warn(p_company uuid, p_step text, p_error text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  raise warning 'NEXA: hourly close of company %, step % failed: %', p_company, p_step, p_error;
  insert into public.job_runs (job_name, run_key, status, finished_at, error, details)
  values ('company_hour_step', p_company::text || ':' || p_step, 'failed', now(), left(p_error, 500),
          jsonb_build_object('failures', 1, 'step', p_step, 'company_id', p_company))
  on conflict (job_name, run_key) do update
    set status = 'failed', finished_at = now(), error = excluded.error,
        details = jsonb_build_object('failures', coalesce((public.job_runs.details ->> 'failures')::integer, 0) + 1,
                                     'step', p_step, 'company_id', p_company);
end;
$$;

-- What failed in the last day, for the dashboard
create or replace function public.company_close_warnings_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('step', j.details ->> 'step', 'at', j.finished_at, 'error', left(j.error, 200),
                                               'failures', coalesce((j.details ->> 'failures')::integer, 1))
                            order by j.finished_at desc), '[]'::jsonb)
    from public.job_runs j
   where j.job_name = 'company_hour_step' and j.run_key like p_company::text || ':%' and j.status = 'failed'
     and j.finished_at > now() - interval '24 hours';
$$;

-- The reputation as the company page shows it
create or replace function public.company_reputation_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc   public.player_companies;
  v_l  double precision;
  h    record;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select l.reputation into v_l from public.listed_companies l where l.company_id = p_company;
  select x.reputation_target, x.reputation_drivers, x.hour_start into h from public.player_company_hours x
   where x.company_id = p_company and x.reputation_drivers is not null order by x.hour_start desc limit 1;
  return jsonb_build_object(
    'value', round(coalesce(v_l, pc.reputation)::numeric, 2),
    'target', round(coalesce(h.reputation_target, v_l, pc.reputation)::numeric, 2),
    'demand_factor', round(public.company_reputation_demand_factor(coalesce(v_l, pc.reputation))::numeric, 4),
    'drivers', coalesce(h.reputation_drivers, '{}'::jsonb),
    'at', h.hour_start,
    'history', coalesce((select jsonb_agg(jsonb_build_object('hour_start', y.hour_start, 'value', round(y.reputation::numeric, 2),
                                                             'target', round(coalesce(y.reputation_target, y.reputation)::numeric, 2))
                                          order by y.hour_start)
                           from (select x.hour_start, x.reputation, x.reputation_target from public.player_company_hours x
                                  where x.company_id = p_company and x.reputation is not null
                                  order by x.hour_start desc limit 48) y), '[]'::jsonb));
end;
$$;

-- ---------------------------------------------------------------------------
-- C. Full redefinitions of the listed functions that touch the reputation
-- ---------------------------------------------------------------------------
create or replace function public.listed_ensure(p_company uuid)
returns public.listed_companies
language plpgsql
security definer
set search_path = ''
as $$
declare
  l   public.listed_companies;
  cfg jsonb := public.listed_cfg();
begin
  if not public.listed_is(p_company) then
    return null;
  end if;
  select * into l from public.listed_companies where company_id = p_company;
  if l.company_id is null then
    -- ADR-183: a company going public keeps the reputation it earned as a private company
    insert into public.listed_companies (company_id, reputation, satisfaction, books_until, ai_workers_seen)
    values (p_company,
            coalesce((select pc.reputation from public.player_companies pc where pc.company_id = p_company),
                     public.cfg_num(cfg, '{reputation,start}', 50)),
            public.cfg_num(cfg, '{satisfaction,start}', 60), now(),
            (select pc.ai_workers from public.player_companies pc where pc.company_id = p_company))
    on conflict (company_id) do nothing;
    select * into l from public.listed_companies where company_id = p_company;
  end if;
  return l;
end;
$$;

create or replace function public.listed_reputation_bump(p_company uuid, p_points double precision)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.listed_companies set reputation = least(100.0, greatest(0.0, reputation + coalesce(p_points, 0)))
   where company_id = p_company;
  update public.player_companies pc set reputation = l.reputation
    from public.listed_companies l
   where l.company_id = p_company and pc.company_id = p_company;
$$;

-- The terms of the hour: listed companies as before; private companies get their reputation's demand factor (ADR-183)
create or replace function public.listed_hour_effect(p_company uuid, p_hour_start timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  l    public.listed_companies;
  v_df double precision := 1;
begin
  l := public.listed_ensure(p_company);
  if l.company_id is null then
    begin
      v_df := public.company_reputation_demand_factor(
                (select pc.reputation from public.player_companies pc where pc.company_id = p_company));
    exception when others then
      v_df := 1;
    end;
    return jsonb_build_object('awareness_add', 0, 'quality_add', 0, 'demand_factor', coalesce(v_df, 1), 'capacity_factor', 1,
                              'cogs_factor', 1, 'fixed_factor', 1, 'listed', false);
  end if;
  return public.listed_hour_effect_calc(public.listed_effects(p_company), l.satisfaction, l.reputation)
         || jsonb_build_object('listed', true);
end;
$$;

-- After the hour: reputation of every company; for listed ones also finished projects, mood, quits, history, fair
-- value, tax office, board. Every extra step in its own block (ADR-183).
create or replace function public.listed_hour_after(p_company uuid, p_hour_start timestamptz, p_demand double precision,
  p_capacity double precision, p_revenue bigint, p_profit bigint, p_pay_factor_bps integer, p_payout bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg       jsonb := public.listed_cfg();
  rcfg      jsonb := public.company_reputation_cfg();
  l         public.listed_companies;
  pc        public.player_companies;
  c         public.companies;
  v_end     timestamptz := p_hour_start + interval '1 hour';
  v_win     interval;
  v_fx      jsonb;
  v_eff     jsonb;
  v_acc     uuid;
  v_fired   integer;
  v_gone    integer;
  v_heat    double precision;
  v_profit  bigint;
  v_rev     bigint;
  v_pay     bigint;
  v_inv     bigint;
  v_div     bigint;
  v_ratio   integer;
  v_sev     integer;
  v_scandal boolean;
  v_st      jsonb;
  v_rt      jsonb;
  v_op      jsonb := '{}'::jsonb;
  v_target  double precision;
  v_sat     double precision;
  v_rep     double precision;
  v_red     integer;
  v_quit    boolean := false;
  v_today   date := (now() at time zone 'Europe/Berlin')::date;
  v_quits   integer;
  v_pf      double precision;
  v_streak  integer;
  r         record;
begin
  -- warnings of earlier hours are replaced by this hour's
  delete from public.job_runs j where j.job_name = 'company_hour_step' and j.run_key like p_company::text || ':%';

  -- ADR-183: the operational drivers of the reputation, for every company
  begin
    v_op := public.company_reputation_drivers_of(p_company, p_hour_start, p_demand, p_capacity, p_pay_factor_bps);
  exception when others then
    v_op := '{}'::jsonb;
    perform public.company_close_warn(p_company, 'reputation', sqlstate || ': ' || sqlerrm);
  end;

  l := public.listed_ensure(p_company);
  if l.company_id is null then
    -- a private company: only the reputation moves
    begin
      select * into pc from public.player_companies where company_id = p_company;
      v_target := public.company_reputation_target(v_op);
      v_rep := least(100.0, greatest(0.0, coalesce(pc.reputation, 50)
                                          + public.cfg_num(rcfg, '{adjustPerHour}', 0.08) * (v_target - coalesce(pc.reputation, 50))));
      perform public.company_reputation_record(p_company, p_hour_start, v_rep, v_target, v_op);
    exception when others then
      perform public.company_close_warn(p_company, 'reputation', sqlstate || ': ' || sqlerrm);
    end;
    return;
  end if;
  select * into l from public.listed_companies where company_id = p_company for update;
  select * into pc from public.player_companies where company_id = p_company;
  select * into c from public.companies where id = p_company;
  v_acc := public.company_cash_account(p_company);

  -- projects whose time is up become active (research, products, regions, machine levels)
  begin
    perform public.listed_finish_due(p_company, greatest(v_end, now()));
  exception when others then
    perform public.company_close_warn(p_company, 'projects', sqlstate || ': ' || sqlerrm);
  end;

  v_fx := public.listed_effects(p_company);
  v_eff := public.listed_hour_effect_calc(v_fx, l.satisfaction, l.reputation);

  -- dismissals: AI workers gone since the last hour (own quits were already counted out), players fired
  select count(*) into v_fired from public.player_jobs j
   where j.company_id = p_company and j.status = 'ended' and j.end_reason = 'fired'
     and j.ended_at > coalesce(l.layoff_checked_at, now() - interval '1 hour');
  v_gone := greatest(0, coalesce(l.ai_workers_seen, pc.ai_workers) - pc.ai_workers) + coalesce(v_fired, 0);
  v_heat := greatest(0, l.layoff_heat) * (1 - public.cfg_num(cfg, '{satisfaction,layoffs,decayPerHour}', 0.08))
          + v_gone * public.cfg_num(cfg, '{satisfaction,layoffs,perHead}', 3);

  -- the reputation window: profit and revenue of the hours, payouts, withdrawals, investments, dividends
  v_win := make_interval(hours => greatest(1, public.cfg_num(cfg, '{reputation,windowHours}', 24)::integer));
  select coalesce(sum(h.profit_cents), 0), coalesce(sum(h.revenue_cents), 0), coalesce(sum(h.founder_payout_cents), 0)
    into v_profit, v_rev, v_pay
    from public.player_company_hours h where h.company_id = p_company and h.hour_start > v_end - v_win;
  v_pay := v_pay + coalesce((
    select sum(-e.amount_cents) from public.ledger_entries e join public.ledger_transactions t on t.id = e.transaction_id
     where e.account_id = v_acc and e.amount_cents < 0 and e.created_at > now() - v_win
       and t.idempotency_key like 'withdraw:%'), 0);
  select coalesce(sum(-e.amount_cents), 0) into v_inv
    from public.ledger_entries e join public.ledger_transactions t on t.id = e.transaction_id
   where e.account_id = v_acc and e.amount_cents < 0 and e.created_at > now() - v_win
     and t.metadata ->> 'one_off' = 'true';
  select coalesce(sum(d.total_cents), 0) into v_div from public.company_dividends d
   where d.company_id = p_company and d.paid_at > now() - v_win;
  v_ratio := public.listed_payout_ratio_bps(v_pay, v_profit, v_rev);

  select max(e.severity), bool_or(coalesce(cfg #> '{satisfaction,crisis,scandals}', '[]'::jsonb) ? e.archetype)
    into v_sev, v_scandal
    from public.player_company_events e
   where e.company_id = p_company and e.polarity = 'crisis' and e.status in ('open', 'in_force');

  -- mood
  v_st := public.listed_satisfaction_target(public.cfg_num(v_fx, '{satisfaction}', 0), p_pay_factor_bps,
            public.company_pay_mood_bps(p_company), case when p_capacity > 0 then p_demand / p_capacity else 1 end,
            coalesce(v_sev, 0), coalesce(v_scandal, false), v_heat, v_ratio, p_profit);
  v_sat := least(100.0, greatest(0.0, l.satisfaction + public.cfg_num(cfg, '{satisfaction,adjustPerHour}', 0.15)
                                                       * ((v_st ->> 'target')::double precision - l.satisfaction)));
  v_red := case when v_sat < public.cfg_num(cfg, '{satisfaction,red}', 35) then l.red_hours + 1 else 0 end;
  v_quits := case when l.quits_day = v_today then l.quits_today else 0 end;
  if v_red > 0 then
    -- an AI worker leaves every N-th hour in a row in the red zone
    if pc.ai_workers > 0 and v_red % greatest(1, public.cfg_num(cfg, '{satisfaction,quits,everyRedHours}', 3)::integer) = 0 then
      update public.player_companies set ai_workers = ai_workers - 1 where company_id = p_company and ai_workers > 0;
      pc.ai_workers := pc.ai_workers - 1;
      v_quit := true;
      v_quits := v_quits + 1;
      begin
        perform public.social_notify(pc.founder_id, 'team_mood', 'Kündigung bei ' || c.name,
          'Eine KI-Kraft hat hingeschmissen: Die Stimmung ist im Keller.',
          jsonb_build_object('company_id', p_company), '/company', 'quit:' || p_company::text || ':' || p_hour_start::text);
        perform public.company_system_message(p_company, 'Eine KI-Kraft hat gekündigt. Die Stimmung im Team ist schlecht.');
        if v_quits = greatest(1, public.cfg_num(cfg, '{satisfaction,quits,massQuitFrom}', 3)::integer) then
          perform public.feed_post(pc.founder_id, 'mass_quit', jsonb_build_object('company', c.name, 'count', v_quits),
                                   'mass_quit:' || p_company::text || ':' || v_today::text);
        end if;
      exception when others then
        perform public.company_close_warn(p_company, 'quit_notice', sqlstate || ': ' || sqlerrm);
      end;
    end if;
    -- players are not forced out: they are told, at most once per interval
    if l.mood_notified_at is null
       or l.mood_notified_at < now() - make_interval(hours => greatest(1, public.cfg_num(cfg, '{satisfaction,quits,notifyEveryHours}', 24)::integer)) then
      begin
        for r in select j.player_id from public.player_jobs j where j.company_id = p_company and j.status = 'active' loop
          perform public.social_notify(r.player_id, 'team_mood', 'Miese Stimmung bei ' || c.name,
            'Die Zufriedenheit im Team ist im roten Bereich. Vielleicht ist ein anderer Job besser für dich.',
            jsonb_build_object('company_id', p_company), '/career', 'mood:' || p_company::text || ':' || v_today::text);
        end loop;
        perform public.social_notify(pc.founder_id, 'team_mood', 'Stimmung im Keller',
          'Die Mitarbeiterzufriedenheit bei ' || c.name || ' ist im roten Bereich. Kapazität und Qualität sinken.',
          jsonb_build_object('company_id', p_company), '/company', 'mood-f:' || p_company::text || ':' || v_today::text);
      exception when others then
        perform public.company_close_warn(p_company, 'mood_notice', sqlstate || ': ' || sqlerrm);
      end;
      l.mood_notified_at := now();
    end if;
  end if;

  -- reputation: the shareholder target (ADR-167) plus the operational drivers of every company (ADR-183)
  v_streak := case when l.dividend_day is not null and l.dividend_day >= v_today - 1 then l.dividend_streak else 0 end;
  v_rt := public.listed_reputation_target(public.cfg_num(v_fx, '{reputation}', 0), v_pay, v_profit, v_rev, v_inv, v_div,
                                          v_streak, coalesce(v_scandal, false));
  v_target := public.company_reputation_target(v_op, (v_rt ->> 'target')::double precision);
  v_rep := least(100.0, greatest(0.0, l.reputation + public.cfg_num(cfg, '{reputation,adjustPerHour}', 0.08)
                                                     * (v_target - l.reputation)));
  if v_rep < public.cfg_num(cfg, '{reputation,greed,feedBelow}', 35)
     and v_ratio >= public.cfg_num(cfg, '{reputation,greed,fullRatioBps}', 10000) * 0.8 then
    begin
      perform public.feed_post(pc.founder_id, 'greedy_founder', jsonb_build_object('company', c.name, 'ratio_bps', v_ratio),
                               'greedy:' || p_company::text || ':' || v_today::text);
    exception when others then
      perform public.company_close_warn(p_company, 'greed_feed', sqlstate || ': ' || sqlerrm);
    end;
  end if;

  -- the fair share price follows the reputation
  v_pf := 1 + public.cfg_num(cfg, '{reputation,priceMaxEffect}', 0.25) * (v_rep - 50) / 50.0;
  begin
    if c.security_id is not null and v_pf <> l.price_factor then
      update public.security_sim_state
         set fair_value_e4 = greatest(1, round(fair_value_e4 / l.price_factor * v_pf))::bigint
       where security_id = c.security_id;
    end if;
  exception when others then
    v_pf := l.price_factor;
    perform public.company_close_warn(p_company, 'fair_value', sqlstate || ': ' || sqlerrm);
  end;

  update public.listed_companies
     set satisfaction = v_sat, reputation = v_rep, price_factor = v_pf, layoff_heat = v_heat, layoff_checked_at = now(),
         ai_workers_seen = pc.ai_workers, red_hours = v_red, quits_day = v_today, quits_today = v_quits,
         mood_notified_at = l.mood_notified_at, dividend_streak = v_streak
   where company_id = p_company;
  insert into public.listed_company_hours (company_id, hour_start, satisfaction, sat_target, reputation, rep_target, demand_factor,
                                           capacity_factor, upkeep_cents, upkeep, drivers)
  values (p_company, p_hour_start, v_sat, (v_st ->> 'target')::double precision, v_rep, v_target,
          (v_eff ->> 'demand_factor')::double precision, (v_eff ->> 'capacity_factor')::double precision,
          coalesce((select sum(v::bigint) from jsonb_each_text(l.last_upkeep) x(k, v)), 0), l.last_upkeep,
          jsonb_build_object('satisfaction', v_st -> 'drivers', 'reputation', (v_rt -> 'drivers') || v_op,
                             'payout_ratio_bps', v_ratio, 'ai_quit', v_quit))
  on conflict (company_id, hour_start) do nothing;
  delete from public.listed_company_hours h
   where h.company_id = p_company
     and h.hour_start < p_hour_start - make_interval(hours => greatest(24, public.cfg_num(cfg, '{historyHours}', 72)::integer) * 2);
  -- ADR-183: the same value on the company and in the hour row
  perform public.company_reputation_record(p_company, p_hour_start, v_rep, v_target, (v_rt -> 'drivers') || v_op);

  -- missions: an hour in the green zone
  if v_sat >= public.cfg_num(cfg, '{satisfaction,green}', 60) then
    begin
      perform public.mission_event(pc.founder_id, 'satisfaction_green', 1, p_hour_start::text);
    exception when others then
      perform public.company_close_warn(p_company, 'missions', sqlstate || ': ' || sqlerrm);
    end;
  end if;

  -- the tax advisor, the tax office, the board
  begin
    perform public.listed_tax_office(p_company);
  exception when others then
    perform public.company_close_warn(p_company, 'tax_office', sqlstate || ': ' || sqlerrm);
  end;
  begin
    perform public.board_close_due(p_company);
  exception when others then
    perform public.company_close_warn(p_company, 'board', sqlstate || ': ' || sqlerrm);
  end;
end;
$$;

-- CEO interviews (ADR-173) move the reputation of every company now, not only of listed ones (ADR-183)
create or replace function public.company_interview_finish(p_id bigint, p_status text, p_answers jsonb, p_points integer,
                                                           p_now timestamptz)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  e        jsonb := coalesce(public.interviews_cfg() -> 'effects', '{}'::jsonb);
  iv       public.company_interviews;
  v_aw     integer;
  v_rep    double precision;
  v_max    integer := coalesce((e ->> 'maxAwarenessBps')::integer, 300);
  v_maxr   double precision := coalesce((e ->> 'maxReputation')::double precision, 3);
begin
  select * into iv from public.company_interviews where id = p_id for update;
  if iv.id is null or iv.status <> 'requested' then
    return;
  end if;
  v_aw := case p_status
            when 'answered' then greatest(-v_max, least(v_max, coalesce(p_points, 0) * coalesce((e ->> 'awarenessPerPointBps')::integer, 60)))
            when 'declined' then coalesce((e ->> 'declineAwarenessBps')::integer, -80)
            else coalesce((e ->> 'ignoreAwarenessBps')::integer, -120) end;
  v_rep := case when p_status = 'answered' then greatest(-v_maxr, least(v_maxr, coalesce(p_points, 0) * coalesce((e ->> 'reputationPerPoint')::double precision, 0.5)))
                when p_status = 'declined' then coalesce((e ->> 'declineReputation')::double precision, -0.5)
                else coalesce((e ->> 'ignoreReputation')::double precision, -1) end;
  update public.player_companies pc
     set awareness = least(1, greatest(0, coalesce(pc.awareness, 0) + v_aw / 10000.0))
   where pc.company_id = iv.company_id and pc.status = 'active';
  if v_rep <> 0 then
    perform public.listed_ensure(iv.company_id);
    perform public.company_reputation_bump(iv.company_id, v_rep);
  end if;
  update public.company_interviews
     set status = p_status, answers = p_answers, score = p_points, awareness_bps = v_aw, reputation_delta = v_rep,
         answered_at = p_now
   where id = p_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- D. Grants: internal helpers only for the server
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.company_reputation_cfg()',
    'public.company_reputation_drivers(double precision, double precision, double precision, text, integer, bigint, integer, boolean)',
    'public.company_reputation_target(jsonb, double precision)',
    'public.company_reputation_demand_factor(double precision)',
    'public.company_reputation_drivers_of(uuid, timestamptz, double precision, double precision, integer)',
    'public.company_reputation_record(uuid, timestamptz, double precision, double precision, jsonb)',
    'public.company_reputation_bump(uuid, double precision)',
    'public.company_close_warn(uuid, text, text)',
    'public.company_close_warnings_json(uuid)',
    'public.company_reputation_json(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261204007310_company_page_data.sql =====
-- ===== idempotent copy of migrations/20261204007310_company_page_data.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 7310 · Company page data: reputation, close warnings and what each hour used (ADR-183)
-- =============================================================================
-- * company_hours_json: the last 24 closed hours now carry demand, capacity, strengths bonus, AI utilization and the
--   wages paid. "Was jeder leistet" splits the revenue like the hour does (founder and players serve first, the AI
--   workers the rest, ADR-180) and counts the wages actually paid (src/features/company/staff-value.ts); before it
--   split by productivity alone and counted every AI worker at the full wage.
-- * company_state: 'reputation' (every company, ADR-183) and 'close_warnings' (extra steps of the hourly close that
--   failed in the last day). Full redefinition of the latest definition (6600), no text patch.
-- Idempotent: runs unchanged as supabase/updates/20261204007310_company_page_data.sql.

create or replace function public.company_hours_json(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('hour_start', x.hour_start, 'revenue_cents', x.revenue_cents,
                                               'contract_revenue_cents', x.contract_revenue_cents,
                                               'profit_cents', x.profit_cents,
                                               'founder_payout_cents', x.founder_payout_cents,
                                               'stake_payout_cents', x.stake_payout_cents,
                                               'supply_revenue_cents', x.supply_revenue_cents,
                                               'supply_fee_paid_cents', x.supply_fee_paid_cents,
                                               'supply_fee_income_cents', x.supply_fee_income_cents,
                                               'supply_goods_cents', x.supply_goods_cents,
                                               'campaign_id', x.campaign_id)
                            -- ADR-183: what the hour used, for "Was jeder leistet", and the reputation
                            || jsonb_build_object('demand_cents', x.demand_cents,
                                                  'capacity_cents', x.capacity_cents,
                                                  'strength_bonus_cents', x.strength_bonus_cents,
                                                  'ai_utilization_bps', x.ai_utilization_bps,
                                                  'ai_wages_paid_cents', x.ai_wages_paid_cents,
                                                  'player_wages_paid_cents', x.player_wages_paid_cents,
                                                  'reputation', round(x.reputation::numeric, 2))
                            order by x.hour_start), '[]'::jsonb)
    from (select h.* from public.player_company_hours h
           where h.company_id = p_company order by h.hour_start desc limit 24) x;
$$;

create or replace function public.company_state(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  c        public.companies;
  v_team   jsonb;
  v_tier   jsonb;
  v_sb     jsonb;
  v_level  integer;
  v_cash   bigint;
  v_spread double precision;
  v_last   jsonb;
  v_hist   jsonb;
  v_cost   bigint;
  v_mf     double precision;
  v_camp   public.company_campaigns;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  select * into c from public.companies where id = p_company;
  v_team := public.player_company_team(p_company);
  v_tier := public.company_tier_cfg(pc.tier);
  v_sb := public.company_tier_cfg('small_business');
  select p.level into v_level from public.profiles p where p.id = pc.founder_id;
  v_cash := coalesce((select a.balance_cents from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash'), 0);
  v_spread := public.config_double('startups', '{estimate,initialSpread}', 2.3)
            * power(public.config_double('startups', '{estimate,decayPerQuarter}', 0.85), pc.quarters_active);
  select jsonb_build_object(
           'label', r.label, 'demand_cents', r.demand_cents, 'capacity_cents', r.capacity_cents,
           'revenue_cents', r.revenue_cents, 'cogs_cents', r.cogs_cents, 'fixed_cents', r.fixed_cents,
           'ai_worker_cents', r.ai_worker_cents, 'marketing_cents', r.marketing_cents, 'wages_cents', r.wages_cents,
           'operating_profit_cents', r.operating_profit_cents, 'utilization_bps', r.utilization_bps,
           'bonus_cents', r.bonus_cents)
    into v_last
    from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
   where r.company_id = p_company order by gq.ends_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('label', h.label, 'revenue_cents', h.revenue_cents,
                                               'profit_cents', h.operating_profit_cents) order by h.ends_at), '[]'::jsonb)
    into v_hist
    from (select r.label, r.revenue_cents, r.operating_profit_cents, gq.ends_at
            from public.player_company_reports r join public.game_quarters gq on gq.id = r.game_quarter_id
           where r.company_id = p_company order by gq.ends_at desc limit 12) h;
  v_cost := public.company_upgrade_cost(pc.tier);
  -- the estimate describes the market the company reaches (ADR-083)
  v_mf := public.company_market_factor(pc.tier, pc.expansion_level);
  v_camp := public.company_campaign_at(p_company, public.game_now());
  return jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'idea', pc.idea,
    'sector', c.sector_key,
    'color', c.brand_color,
    'logo', public.company_logo(p_company),
    'logo_hidden', pc.logo_hidden,
    'founder_has_job', exists (select 1 from public.player_jobs x where x.player_id = pc.founder_id and x.status = 'active'),
    'full_time_from', public.config_double('startups', '{fullTimeFromEmployees}', 5)::integer,
    'training_from', public.config_double('startups', '{training,fromEmployees}', 5)::integer,
    'headcount', public.company_headcount(p_company),
    'tier', pc.tier,
    'founded_at', c.founded_at,
    'cash_cents', v_cash,
    'value_cents', public.company_value_cents(p_company),
    'unpaid_cents', pc.unpaid_cents,
    'distress', pc.distress,
    'distress_quarters', pc.distress_quarters,
    'grace_quarters', public.config_double('startups', '{insolvency,graceQuarters}', 4)::integer,
    'pay_factor_bps', pc.pay_factor_bps,
    'product_key', public.company_product(p_company) ->> 'key',
    'stage', (v_team ->> 'stage')::integer,
    'stages', public.company_stages_json(p_company),
    'awareness_bps', round(pc.awareness * 10000)::integer,
    'quality_bps', round(pc.quality * 10000)::integer,
    'quarters_active', pc.quarters_active,
    'estimate_low_cents', round(pc.potential_annual_cents * v_mf
                                * exp(-v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':low'))))::bigint,
    'estimate_high_cents', round(pc.potential_annual_cents * v_mf
                                 * exp(v_spread * (0.3 + 0.7 * public.uniform_from_text(pc.company_id::text || ':' || pc.quarters_active || ':high'))))::bigint,
    'marketing_cents_per_quarter', pc.marketing_cents_per_quarter,
    'ai_workers', pc.ai_workers,
    'ai_worker_cost_cents', public.config_bigint('startups', '{aiWorkerCostCentsPerQuarter}', 72000),
    'ai_wage_cents_per_hour', public.config_bigint('startups', '{aiWorkerWageCentsPerHour}', 12000),
    'ai_worker_skills', to_jsonb(pc.ai_worker_skills),
    'max_employees', public.company_max_employees(p_company),
    'employees', (v_team ->> 'employees')::integer,
    'open_postings', (select count(*) from public.job_postings jp where jp.company_id = p_company and jp.status = 'open')::integer,
    'pending_applications', (select count(*) from public.job_applications a join public.job_postings jp on jp.id = a.posting_id
                              where jp.company_id = p_company and a.status = 'pending')::integer,
    'founder_productivity_bps', (v_team ->> 'founder_productivity_bps')::integer,
    'team_productivity_bps', (v_team ->> 'team_productivity_bps')::integer,
    'capacity_cents', round((v_team ->> 'capacity_cents')::bigint * public.company_capacity_factor(pc.expansion_level))::bigint,
    'next_quarter_at', coalesce((public.current_game_quarter()).ends_at, public.game_now()),
    'can_upgrade', public.company_next_tier(pc.tier) is not null
                   and coalesce(v_level, 1) >= (public.company_tier_cfg(public.company_next_tier(pc.tier)) ->> 'minLevel')::integer,
    'listing', public.company_listing_json(p_company, pc.founder_id),
    'can_go_public', c.phase = 'private' and public.company_open_offer(p_company) is null
                     and coalesce(public.config_jsonb('startups', '{ipo,fromTiers}'), '["garage", "small_business", "gmbh"]'::jsonb) ? pc.tier
                     and coalesce(v_level, 1) >= public.config_double('startups', '{ipo,minLevel}', 6),
    'can_capital_increase', c.phase = 'listed' and public.company_open_offer(p_company) is null,
    'upgrade_cost_cents', v_cost,
    'last_quarter', v_last,
    'history', v_hist,
    'live', public.company_live_json(p_company),
    'hours', public.company_hours_json(p_company))
    || jsonb_build_object(
         'banner', pc.banner,
         -- ADR-083: price strategy, contract work, expansion
         'price_level', pc.price_level,
         'contract_work', pc.contract_work,
         'expansion_level', pc.expansion_level,
         'can_expand', public.company_can_expand(pc.tier),
         'expansion_cost_cents', case when public.company_can_expand(pc.tier)
                                      then public.company_expansion_cost_cents(pc.expansion_level) end,
         'market_factor', round(v_mf::numeric, 4),
         -- ADR-086: share of the hourly profit paid to the founder automatically
         'founder_payout_bps', pc.founder_payout_bps,
         -- ADR-097: the running campaign and the current prices (from the demand of the last closed hour)
         'campaign', case when v_camp.id is not null then public.campaign_json(v_camp.id) end,
         'campaign_costs', public.company_campaign_costs(p_company),
         -- ADR-176: slow strengths with their reward, and a stuck hourly close
         'strengths', public.company_strengths_json(p_company),
         -- ADR-183: the reputation of every company and extra steps of the close that failed
         'reputation', public.company_reputation_json(p_company),
         'close_warnings', public.company_close_warnings_json(p_company));
end;
$$;

-- ===== supabase/updates/20261204007800_order_fill_preview.sql =====
-- ===== idempotent copy of migrations/20261204007800_order_fill_preview.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 7800 · The preview is the fill: one plan for quote and execution, capped impact (ADR-189)
-- =============================================================================
-- Bug: "I sold for over 100k and got 50k." The order sheet showed quantity x bid (96.000 EUR), the server filled
-- along the player-impact price path (ADR-126): 1 % per 1.000 EUR for a penny stock, so 96.000 EUR moved the price
-- by 96 % and the average fill was 52 % of the bid (58.877,58 shares at 0,8489 EUR = 49.981 EUR). Nothing capped it.
-- Fix:
-- 1. market_order_plan(): the one fill plan (src/lib/sim/order-fill.ts). The last share of a market order moves the
--    price at most trading.priceImpact.maxImpactBpsPerOrder (15 %) and, for player stocks, stays inside the daily
--    band (ADR-170). Amounts are solved along the price path. Whatever is beyond is not executed and reported.
-- 2. quote_order(): read-only preview with exactly this plan plus fee and the capital gains tax (FIFO lots, loss pot).
-- 3. place_order(): market orders fill exactly the plan (limited_by, unfilled_quantity_e6, impact_bps in the result);
--    nothing fills -> order_impact_limit / price_band_limit. Limit orders are unchanged.
-- Idempotent: runs unchanged as supabase/updates/20261204007800_order_fill_preview.sql.

-- ---------------------------------------------------------------------------
-- A. The fill plan (mirrors planMarketOrder in src/lib/sim/order-fill.ts)
-- ---------------------------------------------------------------------------
create or replace function public.market_order_plan(
  p_security_id  uuid,
  p_side         public.order_side,
  p_quantity_e6  bigint,
  p_amount_cents bigint
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  v_trading   jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_scale     double precision := greatest(1, public.cfg_num(v_trading, '{quantityScale}', 1000000));
  s           public.securities;
  v_bid       bigint;
  v_ask       bigint;
  v_prev      bigint;
  v_last      bigint;
  v_pending   bigint;
  v_touch     bigint;
  v_dir       integer;
  v_a         double precision;
  v_pos       double precision;
  v_fee       bigint;
  v_min_price bigint;
  v_cap       double precision;
  v_band      double precision;
  v_bound     double precision;
  v_band_e4   double precision;
  v_by        text := 'impact';
  v_req       bigint;
  v_max       bigint;
  v_fill      bigint;
  v_avg       bigint;
  v_lastp     bigint;
  v_gross     bigint := 0;
  v_tc        double precision;
  qa          double precision;
  qb          double precision;
  v_disc      double precision;
  v_q         double precision;
begin
  select * into s from public.securities where id = p_security_id;
  select q.bid_e4, q.ask_e4, q.prev_close_e4, q.last_price_e4 into v_bid, v_ask, v_prev, v_last
    from public.security_quotes q where q.security_id = p_security_id;
  if s.id is null or v_bid is null or v_ask is null then
    return null;
  end if;
  select st.pending_player_flow_e6 into v_pending from public.security_sim_state st where st.security_id = s.id;
  v_pending   := coalesce(v_pending, 0);
  v_fee       := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  v_min_price := greatest(1, public.cfg_num(v_trading, '{minPriceE4}', 1))::bigint;
  v_cap       := greatest(0, public.cfg_num(v_trading, '{priceImpact,maxImpactBpsPerOrder}', 1500)) / 10000.0;
  v_a         := public.cfg_num(v_trading, '{priceImpact,impactBpsPerDepth}', 100) / 10000.0
                 / public.security_depth(s.id, public.market_session_at(public.game_now()) = 'regular');
  if p_side = 'buy' then
    v_touch := v_ask;  v_dir := 1;  v_pos := greatest(v_pending, 0) / 1000000.0;
  else
    v_touch := v_bid;  v_dir := -1; v_pos := greatest(-v_pending, 0) / 1000000.0;
  end if;
  if s.kind = 'stock' then
    -- ADR-126: 1 % per depthCentsPer100Bps of value
    v_a := greatest(v_a, 0.01 * (v_touch / 100.0)
                         / greatest(1, public.cfg_num(v_trading,
                                         array['playerImpact', 'depthCentsPer100Bps',
                                               coalesce((select c.tier::text from public.companies c where c.id = s.company_id), 'midcap')],
                                         2500000)));
  end if;

  -- quantity: given, or solved along the price path for the amount
  if p_quantity_e6 is not null then
    v_req := p_quantity_e6;
  else
    v_tc := v_touch / 100.0;                 -- cents per whole share
    qa := v_a / 2 * v_tc;
    if p_side = 'buy' then
      qb := v_tc * (1 + v_a * v_pos);
      v_q := case when qa > 0 then (-qb + sqrt(qb * qb + 4 * qa * greatest(0, p_amount_cents - v_fee))) / (2 * qa)
                  else greatest(0, p_amount_cents - v_fee) / qb end;
      v_req := greatest(0, floor(v_q * v_scale))::bigint;
      if v_req > 0 then
        -- never more than the amount: the average price is rounded to 0,0001 EUR
        v_avg := greatest(v_min_price, round(v_touch * (1 + v_a * (v_pos + v_req / v_scale / 2)))::bigint);
        v_gross := public.value_cents(v_req, v_avg);
        if v_gross > p_amount_cents - v_fee then
          v_req := floor(v_req::double precision * (p_amount_cents - v_fee) / v_gross)::bigint;
        end if;
      end if;
    else
      qb := v_tc * (1 - v_a * v_pos);
      if qa <= 0 then
        v_q := p_amount_cents / qb;
      else
        v_disc := qb * qb - 4 * qa * p_amount_cents;
        v_q := case when v_disc >= 0 then (qb - sqrt(v_disc)) / (2 * qa) else qb / (2 * qa) end;
      end if;
      v_req := greatest(0, ceil(v_q * v_scale))::bigint;
    end if;
  end if;

  -- how far the last share may move the price: the cap, the daily band of player stocks, the minimum price
  v_bound := v_touch * (1 + v_dir * v_cap);
  v_band  := greatest(0, public.cfg_num(v_trading, '{playerStocks,dailyBandBps}', 0)) / 10000.0;
  if s.kind = 'stock' and v_band > 0
     and exists (select 1 from public.player_companies pc where pc.company_id = s.company_id) then
    v_band_e4 := case when v_dir > 0 then ceil(coalesce(v_prev, v_last, v_touch) * (1 + v_band))
                      else floor(coalesce(v_prev, v_last, v_touch) / (1 + v_band)) end;
    if (v_dir > 0 and v_band_e4 < v_bound) or (v_dir < 0 and v_band_e4 > v_bound) then
      v_bound := v_band_e4;
      v_by := 'band';
    end if;
  end if;
  if v_dir < 0 and v_min_price > v_bound then
    v_bound := v_min_price;
  end if;
  if v_a <= 0 then
    v_max := v_req;
  else
    v_max := greatest(0, floor((v_dir * (v_bound / v_touch - 1) / v_a - v_pos) * v_scale))::bigint;
  end if;
  v_fill := least(v_req, v_max);

  if v_fill > 0 then
    v_avg   := greatest(v_min_price, round(v_touch * (1 + v_dir * v_a * (v_pos + v_fill / v_scale / 2)))::bigint);
    v_gross := public.value_cents(v_fill, v_avg);
  else
    v_avg   := v_touch;
    v_gross := 0;
  end if;
  v_lastp := greatest(v_min_price, round(v_touch * (1 + v_dir * v_a * (v_pos + v_fill / v_scale)))::bigint);

  return jsonb_build_object(
    'touch_e4',              v_touch,
    'requested_quantity_e6', v_req,
    'fill_quantity_e6',      v_fill,
    'unfilled_quantity_e6',  v_req - v_fill,
    'avg_price_e4',          v_avg,
    'last_price_e4',         v_lastp,
    'gross_cents',           v_gross,
    'fee_cents',             case when v_fill > 0 then v_fee else 0 end,
    'slippage_bps',          round(abs(v_avg - v_touch)::double precision / v_touch * 10000)::integer,
    'impact_bps',            round(v_dir * v_a * (v_fill / v_scale) * 10000)::integer,
    'limited_by',            case when v_fill < v_req then v_by end,
    'max_quantity_e6',       v_max);
end;
$function$;

revoke all on function public.market_order_plan(uuid, public.order_side, bigint, bigint) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- B. quote_order: the preview the order sheet shows before confirming
-- ---------------------------------------------------------------------------
create or replace function public.quote_order(
  p_ticker       text,
  p_side         text,
  p_quantity_e6  bigint default null,
  p_amount_cents bigint default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  v_player  uuid := public.require_player();
  v_trading jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  s         public.securities;
  v_side    public.order_side;
  v_plan    jsonb;
  v_pos     public.positions;
  v_fill    bigint;
  v_left    bigint;
  v_take    bigint;
  v_cost    bigint := 0;
  v_pnl     bigint;
  v_pot     bigint;
  v_tax     bigint := 0;
  v_gross   bigint;
  v_fee     bigint;
  lot       record;
begin
  if lower(coalesce(p_side, '')) not in ('buy', 'sell') or (p_quantity_e6 is null) = (p_amount_cents is null)
     or coalesce(p_quantity_e6, p_amount_cents) < 1 then
    perform public.api_error('invalid_argument');
  end if;
  v_side := lower(p_side)::public.order_side;
  select * into s from public.securities where id = public.resolve_security(p_ticker);
  if s.id is null then
    perform public.api_error('unknown_security');
  end if;
  v_plan := public.market_order_plan(s.id, v_side, p_quantity_e6, p_amount_cents);
  if v_plan is null then
    perform public.api_error('not_tradable');
  end if;
  v_fill  := (v_plan ->> 'fill_quantity_e6')::bigint;
  v_gross := (v_plan ->> 'gross_cents')::bigint;
  v_fee   := (v_plan ->> 'fee_cents')::bigint;

  -- sells: capital gains tax exactly like execute_fill (FIFO lots, loss pot)
  if v_side = 'sell' and v_fill > 0 then
    select * into v_pos from public.positions p
     where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open';
    if v_pos.id is not null then
      v_left := v_fill;
      for lot in
        select l.quantity_open_e6, l.price_e4 from public.position_lots l
         where l.position_id = v_pos.id and l.quantity_open_e6 > 0 order by l.acquired_at, l.id
      loop
        exit when v_left = 0;
        v_take := least(v_left, lot.quantity_open_e6);
        v_cost := v_cost + public.value_cents(v_take, lot.price_e4);
        v_left := v_left - v_take;
      end loop;
      if v_left > 0 then
        v_cost := v_cost + public.value_cents(v_left, v_pos.avg_entry_price_e4);
      end if;
      v_pnl := v_gross - v_fee - v_cost;
      select pp.tax_loss_pot_cents into v_pot from public.player_private pp where pp.player_id = v_player;
      if v_pnl > 0 then
        v_tax := public.apply_bps(v_pnl - least(v_pnl, coalesce(v_pot, 0)),
                                  public.cfg_num(v_trading, '{capitalGainsTaxBps}', 2500)::numeric);
      end if;
    end if;
  end if;

  return v_plan || jsonb_build_object(
    'ticker',             s.ticker,
    'side',               v_side,
    'tax_cents',          v_tax,
    'realized_pnl_cents', v_pnl,
    -- what the player pays (buy) or receives (sell) in cash
    'net_cents',          case when v_fill = 0 then 0
                               when v_side = 'buy' then v_gross + v_fee
                               else v_gross - v_fee - v_tax end);
end;
$function$;

revoke all on function public.quote_order(text, text, bigint, bigint) from public, anon;
grant execute on function public.quote_order(text, text, bigint, bigint) to authenticated;

-- ---------------------------------------------------------------------------
-- C. place_order: market orders fill exactly the plan (full latest definition, incl. ADR-153 and ADR-170)
-- ---------------------------------------------------------------------------
create or replace function public.place_order(
  p_request_id     uuid,
  p_ticker         text,
  p_side           text,
  p_type           text,
  p_quantity_e6    bigint default null,
  p_limit_price_e4 bigint default null,
  p_amount_cents   bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_player     uuid;
  v_replay     jsonb;
  v_trading    jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_abuse      jsonb := coalesce(public.config_jsonb('abuse'), '{}'::jsonb);
  v_scale      numeric := greatest(1, public.cfg_num(v_trading, '{quantityScale}', 1000000))::numeric;
  v_side       public.order_side;
  v_type       public.order_type;
  v_limit      bigint;
  s            public.securities;
  v_level      integer;
  v_cash       bigint;
  v_bid        bigint;
  v_ask        bigint;
  v_pending    bigint;
  v_regular    boolean;
  v_depth      double precision;
  v_a          double precision;
  v_pos        double precision;
  v_touch      bigint;
  v_qty        bigint;
  v_fill_qty   bigint := 0;
  v_fill_price bigint;
  v_rest       bigint;
  v_fee        bigint;
  v_min_value  bigint;
  v_need       bigint;
  v_reserve    bigint := 0;
  v_avail      bigint;
  v_net_amount bigint;
  v_order_id   uuid := gen_random_uuid();
  v_fill       jsonb;
  o            public.orders;
  v_prof       public.profiles;
  v_min_price  bigint;
  v_plan       jsonb;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'place_order');
  if v_replay is not null then
    return v_replay;
  end if;

  -- inputs -------------------------------------------------------------------
  if lower(coalesce(p_side, '')) not in ('buy', 'sell') or lower(coalesce(p_type, '')) not in ('market', 'limit')
     or (p_quantity_e6 is null) = (p_amount_cents is null) then
    perform public.api_error('invalid_argument');
  end if;
  v_side := lower(p_side)::public.order_side;
  v_type := lower(p_type)::public.order_type;
  if (p_quantity_e6 is not null and p_quantity_e6 < 1) or (p_amount_cents is not null and p_amount_cents < 1) then
    perform public.api_error('invalid_quantity');
  end if;
  if v_type = 'limit' then
    if p_limit_price_e4 is null or p_limit_price_e4 < 1 or p_limit_price_e4 > 100000000000 then
      perform public.api_error('invalid_price');
    end if;
    v_limit := p_limit_price_e4;
  end if;

  select * into s from public.securities where id = public.resolve_security(p_ticker);
  if s.id is null then
    perform public.api_error('unknown_security');
  end if;
  if s.kind not in ('stock', 'bond') or s.status <> 'listed' or not s.is_tradable then
    perform public.api_error('not_tradable');
  end if;
  if (select r.is_paused from public.sim_runtime r where r.id) then
    perform public.api_error('market_paused');
  end if;

  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_type = 'limit' and v_level < public.unlock_level('limit_orders') then
    perform public.api_error('locked');
  end if;
  if s.kind = 'bond' and v_level < public.unlock_level('bonds') then
    perform public.api_error('locked');
  end if;
  -- ADR-170: no buying the own stock with money just taken out of the company
  if v_side = 'buy' and s.kind = 'stock' and public.player_stock_insider_blocked(v_player, s.id) then
    perform public.api_error('insider_cooldown');
  end if;

  if not public.rate_limit_hit(v_player, 'place_order',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerMinute}', 20))::integer, 60)
     or not public.rate_limit_hit(v_player, 'place_order_day',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerDay}', 500))::integer, 86400) then
    perform public.api_error('rate_limited');
  end if;

  -- locks, quote ---------------------------------------------------------------
  v_cash := public.lock_player_accounts(v_player);
  select q.bid_e4, q.ask_e4 into v_bid, v_ask from public.security_quotes q where q.security_id = s.id;
  select st.pending_player_flow_e6 into v_pending from public.security_sim_state st where st.security_id = s.id;
  if v_bid is null or v_ask is null then
    perform public.api_error('not_tradable');
  end if;
  v_pending   := coalesce(v_pending, 0);
  v_regular   := public.market_session_at(public.game_now()) = 'regular';
  v_depth     := public.security_depth(s.id, v_regular);                 -- whole shares
  v_a         := public.cfg_num(v_trading, '{priceImpact,impactBpsPerDepth}', 100) / 10000.0 / v_depth;
  v_fee       := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  v_min_value := greatest(1, public.cfg_num(v_trading, '{minOrderValueCents}', 100))::bigint;
  v_min_price := greatest(1, public.cfg_num(v_trading, '{minPriceE4}', 1))::bigint;
  if v_side = 'buy' then
    v_touch := v_ask;
    v_pos := greatest(v_pending, 0) / 1000000.0;
  else
    v_touch := v_bid;
    v_pos := greatest(-v_pending, 0) / 1000000.0;
  end if;
  -- Stocks: a fill pays for the move it causes (ADR-126). The next tick moves the price by the player impact
  -- (0.01 x value / depthCentsPer100Bps); the fill pays half of that on average, so buying and selling right away
  -- can never earn the move one causes oneself.
  if s.kind = 'stock' then
    v_a := greatest(v_a, 0.01 * (v_touch / 100.0)
                         / greatest(1, public.cfg_num(v_trading,
                                         array['playerImpact', 'depthCentsPer100Bps',
                                               coalesce((select c.tier::text from public.companies c where c.id = s.company_id), 'midcap')],
                                         2500000)));
  end if;

  -- quantity from the amount (neo-broker semantics) ------------------------------
  if p_amount_cents is not null then
    if v_side = 'buy' then
      -- the player pays at most the amount including the fee
      v_net_amount := p_amount_cents - v_fee;
      if v_net_amount < v_min_value then
        perform public.api_error('order_too_small');
      end if;
      if v_type = 'limit' then
        v_qty := floor(v_net_amount * 100000000.0 / v_limit)::bigint;
      else
        -- ADR-189: the quantity the amount buys along the price path, the same plan the preview shows
        v_qty := (public.market_order_plan(s.id, v_side, null, p_amount_cents) ->> 'requested_quantity_e6')::bigint;
      end if;
    else
      -- the amount is the gross proceeds before fee and tax
      if p_amount_cents < v_min_value then
        perform public.api_error('order_too_small');
      end if;
      if v_type = 'limit' then
        v_qty := ceil(p_amount_cents * 100000000.0 / v_limit)::bigint;
      else
        v_qty := (public.market_order_plan(s.id, v_side, null, p_amount_cents) ->> 'requested_quantity_e6')::bigint;
      end if;
    end if;
  else
    v_qty := p_quantity_e6;
  end if;

  if v_qty < 1 then
    perform public.api_error('order_too_small');
  end if;
  if v_qty > public.cfg_num(v_trading, '{maxOrderQuantity}', 100000) * v_scale then
    perform public.api_error('invalid_quantity');
  end if;

  -- sells: free position; >= 99.9 % of it is rounded up to the whole position
  if v_side = 'sell' then
    select p.quantity_e6 - p.reserved_quantity_e6 into v_avail
      from public.positions p
     where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open'
       for update;
    v_avail := coalesce(v_avail, 0);
    if v_qty < v_avail and v_qty * 1000 >= v_avail * 999 then
      v_qty := v_avail;
    end if;
    if v_avail < v_qty then
      perform public.api_error('insufficient_position');
    end if;
  end if;

  -- ADR-153: a stock has a supply. Buyers of one stock go one after the other, so the float cannot be oversold.
  if v_side = 'buy' and s.kind = 'stock' then
    perform 1 from public.securities x where x.id = s.id for update;
    if public.security_free_float_e6(s.id) is not null then
      if public.security_free_float_e6(s.id) < 1 then
        perform public.api_error('no_shares_left');
      end if;
      v_qty := least(v_qty, public.security_free_float_e6(s.id));
    end if;
  end if;

  -- minimum order value at the price it would execute or rest at
  if public.value_cents(v_qty, coalesce(v_limit, v_touch)) < v_min_value
     and not (v_side = 'sell' and v_qty = v_avail) then
    perform public.api_error('order_too_small');
  end if;

  -- how much executes now ---------------------------------------------------------
  if v_type = 'market' then
    -- ADR-189: the fill is exactly the plan the preview (quote_order) showed: the last share moves the price at
    -- most priceImpact.maxImpactBpsPerOrder and stays inside the daily band of player stocks; the rest of a
    -- market order is not executed and reported (limited_by, unfilled_quantity_e6).
    v_plan := public.market_order_plan(s.id, v_side, v_qty, null);
    v_fill_qty := (v_plan ->> 'fill_quantity_e6')::bigint;
    v_fill_price := (v_plan ->> 'avg_price_e4')::bigint;
    if v_fill_qty < 1 then
      perform public.api_error(case when v_plan ->> 'limited_by' = 'band' then 'price_band_limit'
                                    else 'order_impact_limit' end);
    end if;
    v_qty := v_fill_qty;
  elsif v_side = 'buy' and v_touch <= v_limit then
    if v_touch * (1 + v_a * (v_pos + v_qty / v_scale)) <= v_limit then
      v_fill_qty := v_qty;
    else
      v_fill_qty := greatest(0, least(v_qty, floor(((v_limit::double precision / v_touch - 1) / v_a - v_pos) * v_scale)::bigint));
    end if;
  elsif v_side = 'sell' and v_touch >= v_limit then
    if v_touch * (1 - v_a * (v_pos + v_qty / v_scale)) >= v_limit then
      v_fill_qty := v_qty;
    else
      v_fill_qty := greatest(0, least(v_qty, floor(((1 - v_limit::double precision / v_touch) / v_a - v_pos) * v_scale)::bigint));
    end if;
  end if;

  if v_fill_qty > 0 then
    if v_side = 'buy' then
      if v_type = 'limit' then
        v_fill_price := round(v_touch * (1 + v_a * (v_pos + v_fill_qty / v_scale / 2)))::bigint;
      end if;
      if v_type = 'limit' then
        v_fill_price := least(v_fill_price, v_limit);
      end if;
    else
      if v_type = 'limit' then
        v_fill_price := greatest(v_min_price, round(v_touch * (1 - v_a * (v_pos + v_fill_qty / v_scale / 2)))::bigint);
      end if;
      if v_type = 'limit' then
        v_fill_price := greatest(v_fill_price, v_limit);
      end if;
    end if;
  end if;
  v_rest := v_qty - v_fill_qty;

  if v_side = 'buy' then
    v_need := 0;
    if v_fill_qty > 0 then
      v_need := public.value_cents(v_fill_qty, v_fill_price) + v_fee;
    end if;
    if v_rest > 0 then
      v_need := v_need + public.value_cents(v_rest, v_limit) + case when v_fill_qty > 0 then 0 else v_fee end;
    end if;
    if v_need > v_cash then
      perform public.api_error('insufficient_funds');
    end if;
  end if;

  -- order, fill, reservation ---------------------------------------------------------
  insert into public.orders (id, player_id, security_id, request_id, side, type, quantity_e6, limit_price_e4, status)
  values (v_order_id, v_player, s.id, p_request_id, v_side, v_type, v_qty, v_limit, 'pending');

  if v_fill_qty > 0 then
    v_fill := public.execute_fill(v_order_id, v_fill_qty, v_fill_price, false, false);
  end if;

  if v_rest > 0 then
    select * into o from public.orders where id = v_order_id;
    if v_side = 'buy' then
      v_reserve := public.value_cents(v_rest, v_limit) + case when o.fee_cents = 0 then v_fee else 0 end;
      if v_reserve > 0 then
        perform public.ledger_transfer(
          public.ledger_player_account(v_player, 'player_cash'),
          public.ledger_player_account(v_player, 'player_reserve'),
          v_reserve, 'order_reserve', 'Reservierung Limit-Order', 'order', v_order_id,
          'reserve:' || v_order_id::text, v_player);
      end if;
      update public.orders set reserved_cents = v_reserve where id = v_order_id;
    else
      update public.positions p
         set reserved_quantity_e6 = p.reserved_quantity_e6 + v_rest
       where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open';
      update public.orders set reserved_quantity_e6 = v_rest where id = v_order_id;
    end if;
    update public.orders
       set status = case when v_fill_qty > 0 then 'partially_filled'::public.order_status else 'open'::public.order_status end
     where id = v_order_id;
  end if;
  if v_type = 'limit' then
    perform public.mission_event(v_player, 'limit_order', 1, null);
  end if;

  select * into o from public.orders where id = v_order_id;
  select * into v_prof from public.profiles where id = v_player;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'order_id',           o.id,
    'status',             o.status,
    'quantity_e6',        o.quantity_e6,
    'filled_quantity_e6', o.filled_quantity_e6,
    'avg_price_e4',       o.avg_fill_price_e4,
    'gross_cents',        coalesce((v_fill ->> 'gross_cents')::bigint, 0),
    'fee_cents',          o.fee_cents,
    'tax_cents',          coalesce((v_fill ->> 'tax_cents')::bigint, 0),
    'realized_pnl_cents', (v_fill ->> 'realized_pnl_cents')::bigint,
    'cash_cents',         (select a.balance_cents from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash'),
    'reserved_cents',     o.reserved_cents,
    'xp_awarded',         coalesce((v_fill ->> 'xp_awarded')::integer, 0),
    'level',              v_prof.level,
    'xp_total',           v_prof.xp_total,
    'ticker',             s.ticker,
    'side',               o.side,
    'type',               o.type,
    'limit_price_e4',     o.limit_price_e4,
    'amount_cents',       p_amount_cents,
    'requested_quantity_e6', coalesce((v_plan ->> 'requested_quantity_e6')::bigint, o.quantity_e6),
    'unfilled_quantity_e6',  coalesce((v_plan ->> 'requested_quantity_e6')::bigint - o.quantity_e6, 0),
    'limited_by',            v_plan ->> 'limited_by',
    'impact_bps',            coalesce((v_plan ->> 'impact_bps')::integer, 0)));
end;
$function$;

revoke all on function public.place_order(uuid, text, text, text, bigint, bigint, bigint) from public, anon;
grant execute on function public.place_order(uuid, text, text, text, bigint, bigint, bigint) to authenticated;

commit;
